// Length 本段几何长度（毫米；直线 hypot / 弧 |sweep|·r）。
func (t Track) Length() float64 {
	if t.SegType != 2 {
		return math.Hypot(t.X2Mm-t.X1Mm, t.Y2Mm-t.Y1Mm)
	}
	r := t.RadiusMm
	if !(r > 0) {
		r = math.Hypot(t.X1Mm-t.CxMm, t.Y1Mm-t.CyMm)
	}
	if !(r > 0) {
		return 0
	}
	a1 := math.Atan2(t.Y1Mm-t.CyMm, t.X1Mm-t.CxMm)
	a2 := math.Atan2(t.Y2Mm-t.CyMm, t.X2Mm-t.CxMm)
	sweep := a2 - a1
	if t.Clockwise {
		if sweep > 0 {
			sweep -= 2 * math.Pi
		}
	} else if sweep < 0 {
		sweep += 2 * math.Pi
	}
	return math.Abs(sweep) * r
}

