type RectMm struct {
	MinXMm float64
	MinYMm float64
	MaxXMm float64
	MaxYMm float64
}

// WidthMm 宽度。
func (r RectMm) WidthMm() float64 { return r.MaxXMm - r.MinXMm }

// HeightMm 高度。
func (r RectMm) HeightMm() float64 { return r.MaxYMm - r.MinYMm }

// ParseRectV1 解码 rect_v1。
func ParseRectV1(body string) (path string, rect RectMm, err error) {
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "error=") {
			return "", RectMm{}, fmt.Errorf("%s", line)
		}
		if strings.HasPrefix(line, "path=") {
			path = line[5:]
			continue
		}
		if strings.HasPrefix(line, "min_x_mm=") {
			rect.MinXMm = asFloat(line[9:])
		} else if strings.HasPrefix(line, "min_y_mm=") {
			rect.MinYMm = asFloat(line[9:])
		} else if strings.HasPrefix(line, "max_x_mm=") {
			rect.MaxXMm = asFloat(line[9:])
		} else if strings.HasPrefix(line, "max_y_mm=") {
			rect.MaxYMm = asFloat(line[9:])
		}
	}
	return path, rect, nil
}

