// DesignSettings 设计默认设置（键值 map）。
func (b *Board) DesignSettings() (map[string]string, error) {
	body, err := b.RPC.BoardDesignSettings()
	if err != nil {
		return nil, err
	}
	out := map[string]string{}
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "error=") {
			return nil, fmt.Errorf("%s", line)
		}
		if strings.HasPrefix(line, "path=") {
			b.Path = line[5:]
			continue
		}
		if i := strings.IndexByte(line, '='); i > 0 {
			out[line[:i]] = line[i+1:]
		}
	}
	return out, nil
}

// LengthByNet 按网络汇总线长（毫米）。
func (b *Board) LengthByNet() (map[string]float64, error) {
	tracks, err := b.Tracks(false)
	if err != nil {
		return nil, err
	}
	out := map[string]float64{}
	for _, t := range tracks {
		out[t.GetNetname()] += t.Length()
	}
	return out, nil
}

